/** Default-source quote, as shown on the customer rate board. */
public FxQuote quote(String currency, LocalDate date) {
    return fetch(currency, date, null);
}

/**
 * Rate applied to card transactions of the given KST settlement date.
 * On a vendor-closed day the default source only carries the previous business day's rate,
 * so the same date is re-quoted from source 2, which is the vendor's settlement rate for that date.
 */
public BigDecimal settlementRate(String currency, LocalDate date) {
    FxQuote q = quote(currency, date);
    return q.lagged() ? fetch(currency, date, 2).rate() : q.rate();
}

private FxQuote fetch(String currency, LocalDate date, Integer src) {
    String pair = CurrencyPairs.pairOf(currency);
    String key = pair + "@" + date + (src == null ? "" : "@src" + src);
    return cache.computeIfAbsent(key, k -> {
        vendorCalls++;
        return FxqClient.parse(client.rate(pair, date, src));
    });
}

